/bin/bash -lc "node - <<'JS'
const fs=require('fs');
const p='/mnt/data/LSF/data/financebench/processing/BOEING_2018_10K_reconstructed.json';
const data=JSON.parse(fs.readFileSync(p,'utf8'));
const texts=data.texts||[];
console.log('texts',texts.length);
for(let i=0;i<Math.min(40,texts.length);i++){
  const txt=texts[i]&&texts[i].text||'';
  if(txt) console.log('IDX',i,'PAGE',texts[i].page_no,'TXT',txt.slice(0,250).replace(/\\n/g,' '));
}
JS"

